310	    }
311	
312	    /** The household size at or above which an owner earns the household membership points. */
313	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
314	
315	    /** The month (1 July) on which the fiscal year begins. */
316	    public static final int FISCAL_YEAR_START_MONTH = 7;
317	
318	    /**
319	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
320	     * points.
321	     */
322	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
323	
324	    /**
325	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
326	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
327	     * after 1 July belongs to the next calendar year's fiscal year.
328	     */
329	    public static int fiscalYearOf(LocalDate date) {
330	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
331	    }
332	
333	    /**
334	     * The fiscal year carried by the owner's {@link #getMemberId() memberId}, formatted
335	     * {@code 'FY<YY>'} where YY is the two-digit fiscal-year (FY) segment of the memberId (see
336	     * {@link Region#fiscalYearSegmentOf(String)}, which owns the {@code <V2><REGION><FY>} layout).
337	     * Null when no memberId has been assigned (or it is too short to carry an FY segment).
338	     */
339	    public String getFiscalYear() {
340	        String fiscalYearSegment = Region.fiscalYearSegmentOf(this.memberId);
341	        return fiscalYearSegment == null ? null : "FY" + fiscalYearSegment;
342	    }
343	
344	    /**
345	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
346	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
347	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
348	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
349	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
350	     */
351	    public int getMembershipPoints() {
352	        int points = 0;
353	        if (this.email != null && !this.email.isEmpty()) {
354	            points += 2;
355	        }
356	        if (this.namesakeCount != null && this.namesakeCount == 0) {
357	            points += 1;
358	        }
359	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
360	            points += 2;
361	        }
362	        if (this.registrationDate != null
363	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
364	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
365	            points += 3;
366	        }
367	        return points;
368	    }
369	
370	    /**
371	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
372	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
373	     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
374	     */
375	    public int getMembershipLevel() {
376	        int level = computeMembershipLevel();
377	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
378	            return this.membershipLevelCap;
379	        }
380	        return level;
381	    }
382	
383	    /**
384	     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
385	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
386	     */
387	    private int computeMembershipLevel() {
388	        int points = getMembershipPoints();
389	        if (points >= 6) {
390	            return 4;
391	        }
392	        if (points >= 4) {
393	            return 3;
394	        }
395	        if (points >= 2) {
396	            return 2;
397	        }
398	        return 1;
399	    }
400	
401	    /**
402	     * The owner's marketing segment formatted {@code '<TIER>_<AREA>'}, one of
403	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
404	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()} is 3
405	     * or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality (the
406	     * region of its {@code memberId}, see {@link Region#regionOfMemberId(String)}) is a known
407	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}.
408	     */
409	    public String getOwnerSegment() {
410	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
411	        String area = Region.isKnownRegion(Region.regionOfMemberId(this.memberId))
412	                ? "METRO" : "REGIONAL";
413	        return tier + "_" + area;
414	    }
415	
416	    public Integer getMembershipLevelCap() {
417	        return this.membershipLevelCap;
418	    }
419	
420	    public void setMembershipLevelCap(Integer membershipLevelCap) {
421	        this.membershipLevelCap = membershipLevelCap;
422	    }
423	
424	    /**
425	     * The derived version-2 identity key used to detect duplicate owners: the lower-case SHA-256 hex
426	     * digest over {@code V2 + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
427	     * where the telephone is already normalized to E.164 and the email is lower-cased. The fixed
428	     * {@link Region#IDENTITY_VERSION_TAG V2} version tag is mixed into the hash input so every
429	     * version-2 identity key differs from the value version 1 produced; because the tag is a
430	     * constant, owners that collided under version 1 still collide. Two owners are duplicates only
431	     * when their whole identity keys are equal. Because the telephone is part of the key, two owners
432	     * with the same {@code lastName} and {@code postcode} but different telephones have different keys
433	     * and are both allowed (they are instead flagged as a soft match).
434	     */
435	    public String getIdentityKey() {
436	        String tel = this.telephone == null ? "" : this.telephone;
437	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
438	        String soundex = Soundex.encode(this.getLastName());
439	        return Sha256Hex.lowerHex(Region.IDENTITY_VERSION_TAG + "|" + tel + "|" + mail + "|" + soundex);
440	    }
441	
442	    public boolean isSharesHousehold() {
443	        return this.sharesHousehold;
444	    }
445	
446	    public void setSharesHousehold(boolean sharesHousehold) {
447	        this.sharesHousehold = sharesHousehold;
448	    }
449	
450	    public int getHouseholdSize() {
451	        return this.householdSize;
452	    }
453	
454	    public void setHouseholdSize(int householdSize) {
455	        this.householdSize = householdSize;
456	    }
457	
458	    protected Set<Pet> getPetsInternal() {
459	        if (this.pets == null) {
460	            this.pets = new HashSet<>();
461	        }
462	        return this.pets;
463	    }
464	
465	    protected void setPetsInternal(Set<Pet> pets) {
466	        this.pets = pets;
467	    }
468	
469	    public List<Pet> getPets() {
470	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
471	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
472	        return Collections.unmodifiableList(sortedPets);
473	    }
474	
475	    public void setPets(List<Pet> pets) {
476	        this.pets = new HashSet<>(pets);
477	    }
478	
479	    public void addPet(Pet pet) {
480	        getPetsInternal().add(pet);
481	        pet.setOwner(this);
482	    }
483	
484	    /**
485	     * Return the Pet with the given name, or null if none found for this Owner.
486	     *
487	     * @param name to test
488	     * @return true if pet name is already in use
489	     */
490	    public Pet getPet(String name) {
491	        return getPet(name, false);
492	    }
493	
494	    /**
495	     * Return the Pet with the given name, or null if none found for this Owner.
496	     *
497	     * @param name to test
498	     * @return true if pet name is already in use
499	     */
500	    public Pet getPet(String name, boolean ignoreNew) {
501	        name = name.toLowerCase();
502	        for (Pet pet : getPetsInternal()) {
503	            if (!ignoreNew || !pet.isNew()) {
504	                String compName = pet.getName();
505	                compName = compName.toLowerCase();
506	                if (compName.equals(name)) {
507	                    return pet;
508	                }
509	            }
510	        }
511	        return null;
512	    }
513	
514	    public Pet getPet(Integer petId) {
515	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
516	    }
517	
518	    @Override
519	    public String toString() {
520	        return new ToStringCreator(this)
521	
522	            .append("id", this.getId())
523	            .append("new", this.isNew())
524	            .append("lastName", this.getLastName())
525	            .append("firstName", this.getFirstName())
526	            .append("address", this.address)
527	            .append("city", this.city)
528	            .append("telephone", this.telephone)
529	            .toString();
530	    }
531	}
