425	    /**
426	     * Build a version-2 {@code memberId} formatted {@code '<V2><REGION><FY><HASH8><CHK>'}: the fixed
427	     * {@link Region#IDENTITY_VERSION_TAG V2} version tag prefixes the region code, so every
428	     * version-2 memberId differs from the value version 1 produced while the plain region code stays
429	     * readable behind the tag. REGION is the region code derived from the owner's postcode (see
430	     * {@link Region#regionForPostcode(String)}); FY is the two-digit fiscal year of the owner's
431	     * (business-day-adjusted) {@code registrationDate} (see {@link Owner#fiscalYearOf(LocalDate)});
432	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
433	     * the owner's normalized telephone and {@code lastName}; and CHK is a single Luhn check digit
434	     * computed over the digits of {@code <V2><REGION><FY><HASH8>}. The telephone is already
435	     * normalized and the registration date defaulted by {@link #saveOwner(Owner)} before this runs.
436	     * The layout is read back by {@link Region#regionOfMemberId(String)} and
437	     * {@link Region#fiscalYearSegmentOf(String)}; keep them in sync.
438	     */
439	    private String generateMemberId(Owner owner) {
440	        String region = Region.regionForPostcode(owner.getPostcode());
441	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
442	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
443	        String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
444	        LocalDate registrationDate = owner.getRegistrationDate();
445	        String fy = registrationDate == null
446	            ? "00" : String.format("%02d", Owner.fiscalYearOf(registrationDate) % 100);
447	        String base = Region.IDENTITY_VERSION_TAG + region + fy + hash8;
448	        String memberId = base + luhnCheckDigit(base);
449	        return deduplicateMemberId(owner, memberId);
450	    }
