477	    /**
478	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
479	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
480	     * existing owners' {@code memberId}s. The {@code owner} being saved is excluded from the
481	     * comparison so re-saving it does not treat its own id as a collision.
482	     */
483	    private String deduplicateMemberId(Owner owner, String base) {
484	        Set<String> taken = new HashSet<>();
485	        for (Owner existing : ownerRepository.findAll()) {
486	            if (!existing.getId().equals(owner.getId()) && existing.getMemberId() != null) {
487	                taken.add(existing.getMemberId());
488	            }
489	        }
490	        if (!taken.contains(base)) {
491	            return base;
492	        }
493	        int n = 2;
494	        while (taken.contains(base + "-" + n)) {
495	            n++;
496	        }
497	        return base + "-" + n;
498	    }
