 * a known region (see {@link Region}), the postcode must fall within that region's range
 * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
 * postcode.
 *
 * @throws InvalidPostcodeException if the postcode is out of range for the city's region
 */
private void assertPostcodeValid(Owner owner) {
    String postcode = owner.getPostcode();
    if (postcode == null) {
        return;
    }
    String region = Region.forCity(owner.getCity());
    int[] range = region == null ? null : Region.postcodeRange(region);
    if (range == null) {
        return;
    }
    int value = Integer.parseInt(postcode);
    if (value < range[0] || value > range[1]) {
        throw new InvalidPostcodeException(postcode, owner.getCity(), region);
    }
}

/**
 * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
 * server date. The registration date is optional: a {@code null} date is left untouched (it is
 * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
 *
 * @throws FutureRegistrationDateException if the supplied registration date is after today
 */
private void assertRegistrationDateNotFuture(Owner owner) {
    LocalDate registrationDate = owner.getRegistrationDate();
    if (registrationDate == null) {
        return;
    }
    LocalDate today = LocalDate.now();
    if (registrationDate.isAfter(today)) {
        throw new FutureRegistrationDateException(registrationDate, today);
    }
}

/** Email domains rejected as disposable/throwaway addresses. */
private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
    "mailinator.com", "tempmail.com", "guerrillamail.com");

/**
 * The base (second-level) labels of the {@link #DISPOSABLE_EMAIL_DOMAINS}, e.g. {@code
 * "mailinator"} for {@code "mailinator.com"}. A domain is treated as disposable-adjacent when any
 * of its dot-separated labels equals one of these, so subdomains of a disposable domain and the
 * same base name under a different TLD are both caught (see {@link
 * #isEmailDomainDisposableAdjacent(String)}).
 */
private static final Set<String> DISPOSABLE_EMAIL_BASE_LABELS = DISPOSABLE_EMAIL_DOMAINS.stream()
    .map(domain -> domain.substring(0, domain.indexOf('.')))
    .collect(java.util.stream.Collectors.toUnmodifiableSet());

/**
 * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
 * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
 * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
 * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
 *
 * @throws DisposableEmailDomainException if the email domain is blocklisted
 */
private void assertEmailDomainAllowed(Owner owner) {
    String email = owner.getEmail();
    if (email == null) {
        return;
    }
    int at = email.lastIndexOf('@');
    if (at < 0) {
        return;
    }
    String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
    if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
        throw new DisposableEmailDomainException(domain);
    }
}

@Override
@Transactional
public void saveOwner(Owner owner) throws DataAccessException {
    assertPostcodeValid(owner);
    assertRegistrationDateNotFuture(owner);
    if (owner.getTelephone() != null) {
        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
    }
    if (owner.getEmail() != null) {
        owner.setEmail(normalizeEmail(owner.getEmail()));
    }
    assertEmailDomainAllowed(owner);
    applyAddress(owner);
    LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
    owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
    if (owner.getMemberId() == null) {
        owner.setMemberId(generateMemberId(owner));
    }
    boolean creating = owner.isNew();
    if (creating) {
        owner.setNamesakeCount(countNamesakes(owner));
        assertDailyCapacity(owner);
        assertCityCapacity(owner);
    }
    assignHouseholdId(owner);
    assertIdentityUnique(owner);
    applySoftMatch(owner);
    if (creating) {
        applyMembershipLevelCap(owner);
    }
    ownerRepository.save(owner);
    populateHouseholdSize(owner);
    if (creating) {
        AUDIT.info(
            "owner created: id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            owner.getMembershipLevel());
        AUDIT.info(ownerCreatedEvent(owner));
        NOTIFY.info("welcome notification enqueued: ownerId={} memberId={}",
            owner.getId(), owner.getMemberId());
    }
}

/** Schema version of the structured {@code OWNER_CREATED} audit event. */
private static final int AUDIT_SCHEMA_VERSION = 2;

/**
 * Builds the immutable structured {@code OWNER_CREATED} audit event as a compact JSON object
 * {@code {seq, schemaVersion, ownerId, memberId, membershipLevel, ownerSegment, event}}. The
 * {@code seq} is a process-wide, monotonically increasing integer stamped once per created owner;
 * {@code schemaVersion} is the version-2 event schema ({@value #AUDIT_SCHEMA_VERSION}).
 *
 * <p>The identifier field carries the owner's <em>current primary identifier</em>, sourced
 * through {@link #primaryIdentifier(Owner)} — the unified version-2 {@code memberId} — and the
 * {@code ownerSegment} is recomputed from that version-2 identity via
 * {@link Owner#getOwnerSegment()}.
 */
private String ownerCreatedEvent(Owner owner) {
    Map<String, Object> event = new LinkedHashMap<>();
    event.put("seq", OWNER_CREATED_SEQ.incrementAndGet());
    event.put("schemaVersion", AUDIT_SCHEMA_VERSION);
    event.put("ownerId", owner.getId());
    event.put("memberId", primaryIdentifier(owner));
    event.put("membershipLevel", owner.getMembershipLevel());
    event.put("ownerSegment", owner.getOwnerSegment());
    event.put("event", "OWNER_CREATED");
    return AUDIT_MAPPER.writeValueAsString(event);
}

/**
 * The owner's current primary identifier — the unified {@code memberId}. This is the single
 * place to switch so every consumer (notably the structured audit event) follows.
 */
private String primaryIdentifier(Owner owner) {
    return owner.getMemberId();
}

/**
 * Build a version-2 {@code memberId} formatted {@code '<V2><REGION><FY><HASH8><CHK>'}: the fixed
 * {@link Region#IDENTITY_VERSION_TAG V2} version tag prefixes the region code, so every
 * version-2 memberId differs from the value version 1 produced while the plain region code stays
 * readable behind the tag. REGION is the region code derived from the owner's postcode (see
 * {@link Region#regionForPostcode(String)}); FY is the two-digit fiscal year of the owner's
 * (business-day-adjusted) {@code registrationDate} (see {@link Owner#fiscalYearOf(LocalDate)});
 * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
 * the owner's normalized telephone and {@code lastName}; and CHK is a single Luhn check digit
 * computed over the digits of {@code <V2><REGION><FY><HASH8>}. The telephone is already
 * normalized and the registration date defaulted by {@link #saveOwner(Owner)} before this runs.
 * The layout is read back by {@link Region#regionOfMemberId(String)} and
 * {@link Region#fiscalYearSegmentOf(String)}; keep them in sync.
 */
private String generateMemberId(Owner owner) {
    String region = Region.regionForPostcode(owner.getPostcode());
    String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
    String lastName = owner.getLastName() == null ? "" : owner.getLastName();
    String hash8 = Sha256Hex.upperHex(telephone + lastName, 8);
    LocalDate registrationDate = owner.getRegistrationDate();
    String fy = registrationDate == null
        ? "00" : String.format("%02d", Owner.fiscalYearOf(registrationDate) % 100);
    String base = Region.IDENTITY_VERSION_TAG + region + fy + hash8;
    String memberId = base + luhnCheckDigit(base);
    return deduplicateMemberId(owner, memberId);
}

/**
 * A single Luhn check digit (0-9) computed over the decimal digits contained in {@code value}
 * (non-digit characters, such as the region letters and hex letters, are ignored).
 */
private static int luhnCheckDigit(String value) {
    int sum = 0;
    boolean dbl = true;
    for (int i = value.length() - 1; i >= 0; i--) {
        char c = value.charAt(i);
        if (c < '0' || c > '9') {
            continue;
        }
        int d = c - '0';
        if (dbl) {
            d *= 2;
            if (d > 9) {
                d -= 9;
            }
        }
        sum += d;
        dbl = !dbl;
    }
    return (10 - (sum % 10)) % 10;
}

/**
 * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
 * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
 * existing owners' {@code memberId}s. The {@code owner} being saved is excluded from the
 * comparison so re-saving it does not treat its own id as a collision.
 */
private String deduplicateMemberId(Owner owner, String base) {
    Set<String> taken = new HashSet<>();
    for (Owner existing : ownerRepository.findAll()) {
        if (!existing.getId().equals(owner.getId()) && existing.getMemberId() != null) {
            taken.add(existing.getMemberId());
        }
    }
    if (!taken.contains(base)) {
        return base;
    }
    int n = 2;
    while (taken.contains(base + "-" + n)) {
        n++;
    }
    return base + "-" + n;
}

/** Maximum number of owners permitted in a single city. */
private static final long CITY_OWNER_LIMIT = 50L;

/** A city with at least this many owners (but below {@link #CITY_OWNER_LIMIT}) raises the
 *  approaching-capacity warning. */
private static final long CITY_CAPACITY_WARNING_THRESHOLD = 40L;

/**
 * Reports whether {@code city} is approaching the per-city capacity limit, i.e. it already holds
 * between {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@code CITY_OWNER_LIMIT - 1} owners
 * (inclusive), reusing the same per-city count as the hard limit ({@link #assertCityCapacity}).
 */
@Override
@Transactional(readOnly = true)
public boolean isCityCapacityWarningActive(String city) throws DataAccessException {
    if (city == null) {
        return false;
    }
    long count = countOwnersInCity(city);
    return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_OWNER_LIMIT;
}

/**
 * Reports whether {@code city} is over its soft capacity, i.e. it already holds at least
 * {@link #CITY_CAPACITY_WARNING_THRESHOLD} owners. Unlike {@link #isCityCapacityWarningActive},
 * this has no upper bound, so it stays true once the city reaches or exceeds the hard limit.
 */
@Override
@Transactional(readOnly = true)
public boolean isCityOverSoftCapacity(String city) throws DataAccessException {
    if (city == null) {
        return false;
    }
    return countOwnersInCity(city) >= CITY_CAPACITY_WARNING_THRESHOLD;
}

/**
 * Reports whether {@code email}'s domain is disposable-adjacent: any of the domain's
 * dot-separated labels equals a {@link #DISPOSABLE_EMAIL_BASE_LABELS disposable base label}, so a
 * subdomain of a disposable domain and the same base name under a different TLD are both caught.
 * Returns false when the email is null or has no domain part. The comparison is case-insensitive.
 */
@Override
@Transactional(readOnly = true)
public boolean isEmailDomainDisposableAdjacent(String email) throws DataAccessException {
    if (email == null) {
        return false;
    }
    int at = email.lastIndexOf('@');
    if (at < 0) {
        return false;
    }
    String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
    if (domain.isEmpty()) {
        return false;
    }
    for (String label : domain.split("\\.")) {
        if (DISPOSABLE_EMAIL_BASE_LABELS.contains(label)) {
            return true;
        }
    }
    return false;
}

/**
 * Composes the aggregate owner risk flag from its three signals: true when the owner is a
 * possible duplicate, its email domain is {@link #isEmailDomainDisposableAdjacent(String)
 * disposable-adjacent}, or its city is {@link #isCityOverSoftCapacity(String) over its soft
 * capacity}; false otherwise. Single authoritative home for the spec's OR-composition.
 */
@Override
@Transactional(readOnly = true)
public boolean isOwnerRiskFlagged(boolean possibleDuplicate, String email, String city)
        throws DataAccessException {
    return possibleDuplicate
        || isEmailDomainDisposableAdjacent(email)
        || isCityOverSoftCapacity(city);
}

/**
 * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
 * more owners, so no city can grow beyond the capacity limit.
 *
 * @throws CityOwnerLimitException if the owner's city is already at capacity
 */
private void assertCityCapacity(Owner owner) {
    if (owner.getCity() == null) {
        return;
    }
    if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
        throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
    }
}

/** Fixed public holidays that the business-day roll skips. */
private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
        LocalDate.parse("2026-12-28"));

