56	     * form a valid E.164 number.
57	     *
58	     * @param raw the raw telephone number as supplied by the client (may be {@code null})
59	     * @return the normalized {@code +<digits>} string, or {@code null} when invalid
60	     */
61	    public static String toE164(String raw) {
62	        if (raw == null) {
63	            return null;
64	        }
65	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
66	        String digits;
67	        if (cleaned.startsWith("+")) {
68	            String body = cleaned.substring(1);
69	            if (!body.matches("\\d+")) {
70	                return null;
71	            }
72	            digits = body;
73	        }
74	        else {
75	            if (!cleaned.matches("\\d+")) {
76	                return null;
77	            }
78	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
79	            digits = "61" + national;
80	        }
81	        if (digits.length() < 8 || digits.length() > 15) {
